  groupIssuesByPage(issues) {
    const general = [];
    const byPage = {};
    const pages = [];
    for (const issue of issues) {
      if (!issue) {
        continue;
      }
      if (!issue.page) {
        general.push(issue);
      } else {
        const pageNum = issue.page;
        if (!byPage[pageNum]) {
          byPage[pageNum] = [];
          pages.push(pageNum);
        }
        byPage[pageNum]?.push(issue);
      }
    }
    pages.sort((a, b) => {
      return a - b;
    });
    return {
      byPage,
      general,
      pages
    };
  }
